#!/usr/bin/env python3
"""A small, pure Python implementation of GNU ed's documented interface."""
import sys, os, stat, ctypes

class EdError(Exception): pass
class QuitEd(Exception): pass

# POSIX regex from libc gives leftmost-longest matching (unlike Python re).
_libc = ctypes.CDLL(None)
_libc.regcomp.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_int]
_libc.regcomp.restype = ctypes.c_int
_libc.regexec.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_int]
_libc.regexec.restype = ctypes.c_int
_libc.regfree.argtypes = [ctypes.c_void_p]
class RM(ctypes.Structure):
    _fields_ = [('so', ctypes.c_int), ('eo', ctypes.c_int)]

class Regex:
    def __init__(self, pat, extended=False, icase=False):
        self.mem = ctypes.create_string_buffer(4096)
        flags = (1 if extended else 0) | (2 if icase else 0)
        if _libc.regcomp(self.mem, pat.encode('latin1'), flags):
            raise EdError()
    def __del__(self):
        try: _libc.regfree(self.mem)
        except Exception: pass
    def match(self, text, start=0, groups=10):
        b = text.encode('latin1')
        m = (RM * groups)()
        rc = _libc.regexec(self.mem, b[start:], groups, m, 1 if start else 0)
        if rc: return None
        out = []
        for x in m:
            out.append(None if x.so < 0 else (start+x.so, start+x.eo))
        return out

class Line:
    nextid = 1
    def __init__(self, text, ident=None):
        self.text = text
        self.id = ident if ident is not None else Line.nextid
        if ident is None: Line.nextid += 1

class Editor:
    def __init__(self, argv):
        self.extended=False; self.loose=False; self.quiet=False; self.restricted=False
        self.script=False; self.prompt='*'; self.prompt_on=False
        self.filename=None; self.lines=[]; self.cur=0; self.cut=[]; self.marks={}
        self.modified=False; self.undo_state=None; self.last_regex=None
        self.last_search=None; self.last_sub_regex=None; self.last_repl=None
        self.last_sub_global=False; self.last_sub_count=1; self.last_sub_print=''
        self.last_interactive=None; self.had_error=False; self.warned=False
        self.inp=sys.stdin.buffer; self.out=sys.stdout.buffer
        try: self.input_regular=stat.S_ISREG(os.fstat(0).st_mode)
        except OSError: self.input_regular=False
        self.parse_args(argv)
        if self.filename is not None:
            try: self.load_initial(self.filename)
            except EdError:
                # A missing command-line file is nonfatal when input is not a tty.
                self.lines=[]; self.cur=0

    def parse_args(self, a):
        i=0
        while i<len(a) and a[i].startswith('-') and a[i] != '-':
            x=a[i]
            if x=='-E': self.extended=True
            elif x=='-l': self.loose=True
            elif x=='-q': self.quiet=True
            elif x=='-r': self.restricted=True
            elif x=='-s': self.script=True
            elif x=='-p':
                i+=1
                if i>=len(a): raise SystemExit(1)
                self.prompt=a[i]; self.prompt_on=True
            else: raise SystemExit(1)
            i+=1
        if len(a)-i>1: raise SystemExit(1)
        if i<len(a): self.filename=a[i]

    def emit(self, s): self.out.write(s.encode('latin1')); self.out.flush()
    def error(self):
        self.emit('?\n'); self.had_error=True
        if self.input_regular: raise QuitEd()
    def check_name(self, name):
        if not name or name.startswith('!'): raise EdError()
        if self.restricted and ('/' in name or name in ('.','..')): raise EdError()
    def read_file(self, name):
        self.check_name(name)
        try:
            data=open(name,'rb').read()
        except OSError: raise EdError()
        parts=data.split(b'\n')
        if parts and parts[-1]==b'': parts.pop()
        return [Line(x.decode('latin1')) for x in parts], len(data)
