        ls,n=self.read_file(name); self.lines=ls; self.cur=len(ls)
        if not self.script: self.emit(str(n)+'\n')
    def snapshot(self):
        return ([(x.text,x.id) for x in self.lines], self.cur, dict(self.marks),
                [x.text for x in self.cut], self.modified)
