        self.lines=[Line(t,i) for t,i in raw]; self.cut=[Line(t) for t in cut]
        self.undo_state=now
    def begin_change(self): self.undo_state=self.snapshot()
    def changed(self): self.modified=True; self.warned=False
    def read_raw(self):
        if self.prompt_on: self.emit(self.prompt)
        b=self.inp.readline()
        if b==b'': return None
        return b[:-1] if b.endswith(b'\n') else b
    def read_text(self):
        out=[]
        while True:
            b=self.inp.readline()
            if b==b'': break
            if b.endswith(b'\n'): b=b[:-1]
            s=b.decode('latin1')
            if s=='.': break
            out.append(Line(s))
        return out
    def compile(self,pat,icase=False, empty_ok=True, search=False):
        if pat=='':
            if icase or not empty_ok or self.last_regex is None: raise EdError()
            r=self.last_regex
        else:
            r=Regex(pat,self.extended,icase); self.last_regex=r
        if search: self.last_search=r
        return r
    def delimited(self,s,p,delim):
        start=p; esc=False
        while p<len(s):
            c=s[p]
            if c==delim and not esc: return s[start:p],p+1,True
            if c=='\\' and not esc: esc=True
            else: esc=False
            p+=1
        return s[start:p],p,False
    def search_addr(self,r,forward=True):
        if not self.lines: raise EdError()
        n=len(self.lines)
        for k in range(1,n+1):
            a=(self.cur-1+(k if forward else -k))%n+1
            if r.match(self.lines[a-1].text) is not None: return a
        raise EdError()
    def one_addr(self,s,p):
        n=len(s); base=None
        while p<n and s[p] in ' \t': p+=1
        if p>=n: return None,p
        c=s[p]
        if c=='.': base=self.cur; p+=1
        elif c=='$': base=len(self.lines); p+=1
        elif c=="'":
            if p+1>=n or s[p+1] not in 'abcdefghijklmnopqrstuvwxyz': raise EdError()
            ident=self.marks.get(s[p+1]); p+=2
            base=next((i+1 for i,x in enumerate(self.lines) if x.id==ident),None)
            if base is None: raise EdError()
        elif c in '/?':
            pat,p,closed=self.delimited(s,p+1,c)
            if not closed: raise EdError()
            ic=False
            if p<n and s[p]=='I': ic=True; p+=1
            base=self.search_addr(self.compile(pat,icase=ic,search=True),c=='/')
        elif c.isdigit():
            q=p
            while p<n and s[p].isdigit(): p+=1
            base=int(s[q:p])
        elif c in '+-': base=self.cur
        else: return None,p
        while True:
            save=p
            while p<n and s[p] in ' \t': p+=1
            if p<n and s[p] in '+-':
                sign=1 if s[p]=='+' else -1; p+=1; q=p
                while p<n and s[p].isdigit(): p+=1
                base += sign*(int(s[q:p]) if p>q else 1)
            elif p<n and s[p].isdigit():
                q=p
                while p<n and s[p].isdigit(): p+=1
                base += int(s[q:p])
            else:
                p=save; break
        if base<0 or base>len(self.lines): raise EdError()
        return base,p
    def addresses(self,s):
        p=0; vals=[]; semi=False
        a,p2=self.one_addr(s,p)
        if a is not None: vals.append(a); p=p2
        while True:
            q=p
            while q<len(s) and s[q] in ' \t': q+=1
            if q>=len(s) or s[q] not in ',;': break
            sep=s[q]; p=q+1
            if not vals: vals.append(1 if sep==',' else self.cur)
            if sep==';': self.cur=vals[-1]; semi=True
            a,p2=self.one_addr(s,p)
            if a is None: a=len(self.lines)
            vals.append(a); p=p2
        return vals[-2:],p,semi
    def rng(self,addrs,default,zero=False):
        if not addrs: a,b=default
        elif len(addrs)==1: a=b=addrs[0]
        else: a,b=addrs
        if a>b or a<0 or b>len(self.lines) or (not zero and a==0): raise EdError()
        return a,b
    def noaddr(self,a):
        if a: raise EdError()
    def suffix(self,rest):
        if any(c not in 'pln' for c in rest) or len(set(rest))!=len(rest): raise EdError()
        return rest
    def print_range(self,a,b,mode='p'):
        if a<1 or b>len(self.lines) or a>b: raise EdError()
        for i in range(a,b+1):
            text=self.lines[i-1].text
            pref=(str(i)+'\t') if 'n' in mode else ''
            if 'l' in mode: self.emit(pref+self.list_text(text))
            else: self.emit(pref+text+'\n')
        self.cur=b
    def list_text(self,t):
        out=''
        mp={'\\':'\\\\','\a':'\\a','\b':'\\b','\f':'\\f','\r':'\\r','\t':'\\t','\v':'\\v','$':'\\$'}
        for c in t:
            o=ord(c)
            out += mp.get(c, c if 32<=o<127 else '\\%03o'%o)
        out+='$'
        # GNU ed wraps list output at 70 columns, ending continued rows in backslash.
        rows=[]
        while len(out)>70: rows.append(out[:69]+'\\\n'); out=out[69:]
        return ''.join(rows)+out+'\n'
    def apply_suffix(self,suf):
        if suf: self.print_range(self.cur,self.cur,suf)
    def file_arg(self,rest):
        if rest=='': return None
        if rest[0] not in ' \t': raise EdError()
        return rest.strip(' \t')
    def logical_continuation(self,first):
        parts=[first]
        while parts[-1].endswith('\\'):
            parts[-1]=parts[-1][:-1]
            b=self.inp.readline()
            if b==b'': break
            if b.endswith(b'\n'): b=b[:-1]
            parts.append(b.decode('latin1'))
        return '\n'.join(parts)

