            pat,p,ok=self.delimited(rest,1,d)
            if not ok: raise EdError()
            repl,p,closed=self.delimited(rest,p,d)
            flags=rest[p:]
            implied_print=not closed
            if repl=='%':
                if self.last_repl is None: raise EdError()
                repl=self.last_repl
            r=self.compile(pat,False); self.last_sub_regex=r; self.last_repl=repl
            glob=False; count=1; pm=''; ic=False
            q=0
            while q<len(flags):
                c=flags[q]
                if c=='g':
                    if glob: raise EdError()
                    glob=True; q+=1
                elif c.isdigit():
                    z=q
                    while q<len(flags) and flags[q].isdigit(): q+=1
                    count=int(flags[z:q])
                    if count<1: raise EdError()
                elif c in 'pln':
                    if c in pm: raise EdError()
                    pm+=c; q+=1
                elif c in 'Ii': ic=True; q+=1
                else: raise EdError()
            if glob and count!=1: raise EdError()
            if ic:
                if pat=='': raise EdError()
                r=Regex(pat,self.extended,True); self.last_regex=r; self.last_sub_regex=r
            if implied_print: pm+='p'
        else:
            if self.last_sub_regex is None: raise EdError()
            r=self.last_sub_regex; repl=self.last_repl
            glob=self.last_sub_global; count=self.last_sub_count; pm=self.last_sub_print
            q=0
            while q<len(rest):
                c=rest[q]
                if c=='g': glob=not glob; count=1; q+=1
                elif c.isdigit():
                    z=q
                    while q<len(rest) and rest[q].isdigit(): q+=1
                    count=int(rest[z:q]); glob=False
                elif c=='p': pm='' if pm else 'p'; q+=1
                elif c=='r':
                    if self.last_search is None: raise EdError()
                    r=self.last_search; q+=1
                else: raise EdError()
        self.last_sub_global=glob; self.last_sub_count=count; self.last_sub_print=pm
        changed=[]; replacements={}
        for idx in range(a-1,b):
            text=self.lines[idx].text; pos=0; occurrence=0; pieces=[]; anyrep=False
            while pos<=len(text):
                m=r.match(text,pos)
                if m is None: break
                occurrence+=1; x,y=m[0]
                take=glob or occurrence==count
                if take:
                    pieces.append(text[pos:x]); pieces.append(self.expand_repl(repl,text,m)); anyrep=True
                else: pieces.append(text[pos:y])
                if y==x:
                    if y<len(text): pieces.append(text[y:y+1]); pos=y+1
                    else: pos=y; break
                else: pos=y
                if take and not glob: break
            if anyrep:
                pieces.append(text[pos:]); replacements[idx]=''.join(pieces).split('\n'); changed.append(idx)
        if not changed: raise EdError()
        self.begin_change(); shift=0; last=0
        for idx in changed:
            real=idx+shift; old=self.lines[real]; vals=replacements[idx]
            self.cut=[Line(old.text)]
