        d=rest[0]
        if d in ' \t\n': raise EdError()
        pat,p,closed=self.delimited(rest,1,d)
        if not closed: raise EdError()
        ic=False
        if p<len(rest) and rest[p]=='I': ic=True; p+=1
        r=self.compile(pat,icase=ic)
