            else: s=raw.decode('latin1')
            try: self.execute(s)
            except EdError:
                try: self.error()
                except QuitEd: break
            except QuitEd: break
        return 0 if (self.loose or not self.had_error) else 1

def main(argv):
    try: return Editor(argv).run()
    except (EdError, OSError): return 1
if __name__=='__main__': sys.exit(main(sys.argv[1:]))
